<div class="forum-workspace"><nav class="forum-boards" aria-label="讨论板块"><a class="<?= !Yii::$app->request->get('category')?'active':'' ?>" href="/forum">全部板块</a><?php foreach($categories as $c): ?><a class="<?= Yii::$app->request->get('category')==$c->id?'active':'' ?>" href="/forum?category=<?= (int)$c->id ?>"><?= e($c->name) ?> <span>↗</span></a><?php endforeach ?></nav><div class="forum-main"><div class="tab-bar"><a href="/forum" <?= !Yii::$app->request->get('feed')&&!Yii::$app->request->get('mine')?'class="active"':'' ?>>最新讨论</a><a href="/forum?feed=main" <?= Yii::$app->request->get('feed')==='main'?'class="active"':'' ?>>我的主队</a><a href="/forum?mine=1" <?= Yii::$app->request->get('mine')==='1'?'class="active"':'' ?>>我的主题</a></div>
