<div class="thread-list list-group"><?php foreach($provider->models as $t): ?><article class="thread-row list-group-item"><span class="avatar thread-avatar" aria-hidden="true"><?= e(mb_substr($t->author?->displayName??'球迷',0,1)) ?></span><div class="thread-main list-group-item-content"><div class="meta"><span><?= e($t->category?->name) ?></span><?php if($t->is_pinned): ?><b class="badge">置顶</b><?php endif ?><?php if($t->is_locked): ?><span>已锁定</span><?php endif ?><?php if($t->team): ?><a href="/forum?team_id=<?= (int)$t->team_id ?>"><?= TeamUi::label($t->team) ?></a><?php endif ?></div><h2><a href="/forum/<?= (int)$t->id ?>"><?= e($t->title) ?></a></h2><p><?= e(mb_substr($t->body,0,100)) ?></p><div class="thread-byline"><span><?= e($t->author?->displayName??'球迷') ?></span><?php if($t->author?->profile?->mainTeam): ?><span class="team-badge"><?= TeamUi::label($t->author->profile->mainTeam) ?></span><?php endif ?><time><?= e(date('m月d日 H:i',strtotime($t->last_activity_at))) ?></time></div></div><div class="thread-count list-group-item-meta"><b><?= (int)$t->reply_count ?></b><small>回复</small><span>♡ <?= (int)$t->like_count ?></span></div></article><?php endforeach ?><?php if(!$provider->models): ?><div class="empty"><h2>还没有相关讨论</h2><a href="/forum/new" class="button">发起讨论 ↗</a></div><?php endif ?></div><?= yii\widgets\LinkPager::widget(['pagination'=>$provider->pagination]) ?></div><aside class="forum-sidebar"><div class="forum-profile-card"><span class="mini-crest" aria-hidden="true">W</span><h3>我的球迷档案</h3><?php $main=Yii::$app->user->identity?->profile?->mainTeam; ?><?php if($main): ?><p><?= TeamUi::label($main) ?></p><?php endif ?><a class="button" href="/profile"><?= $main?'管理主队与收藏':'选择我的主队' ?> ↗</a></div><div class="forum-numbers"><div><b><?= (int)\app\models\ForumThread::find()->where(['status'=>'published'])->count() ?></b><span>讨论主题</span></div><div><b><?= (int)\app\models\ForumReply::find()->where(['status'=>'visible'])->count() ?></b><span>球迷回复</span></div></div><details class="forum-rules"><summary>论坛规则</summary><p>理性讨论，尊重他人。请勿刷屏、辱骂或发布广告。</p></details></aside></div>
